const REQUIRED_KEYS = ["tailored_summary","tailored_skills_order","tailored_body_latex","cover_letter"];
const PLACEHOLDER_COMPANIES = ["example corp","abc company","xyz inc","sample company","your company","acme inc"];
const resp = $input.item.json;
let text = "";
if (resp.candidates && resp.candidates[0] && resp.candidates[0].content && resp.candidates[0].content.parts && resp.candidates[0].content.parts[0] && resp.candidates[0].content.parts[0].text) { text = resp.candidates[0].content.parts[0].text; }
let tailored = null;
let parseError = null;
try { tailored = JSON.parse(text); } catch (e) { parseError = e.message; }
const candidateId = $("Normalize Input").item.json.candidate_id;
const candidateEmail = $("Normalize Input").item.json.candidate_email;
const originalCvTex = $("Normalize Input").item.json.original_cv_tex;
const selectedJob = $("Normalize Input").item.json.selected_job;
const unsupported = [];
if (parseError) { unsupported.push("Invalid JSON: " + parseError); }
if (tailored) {
  for (const k of REQUIRED_KEYS) { if (tailored[k] === undefined) { unsupported.push("Missing field: " + k); } }
  const rawLower = (originalCvTex || "").toLowerCase();
  const missing = (selectedJob.missing_skills || []).map(function(s){ return (s||"").toLowerCase(); });
  const matchedRequired = (selectedJob.matched_skills || []).map(function(s){ return (s||"").toLowerCase(); });
  function containsAny(t, list) { const tl = (t || "").toLowerCase(); return list.filter(function(m) { return m && tl.indexOf(m) !== -1; }); }
  (tailored.tailored_skills_order || []).forEach(function(skill) { if (rawLower.indexOf((skill || "").toLowerCase()) === -1) { unsupported.push("tailored_skills_order item not in original CV: " + skill); } });
  containsAny(tailored.tailored_summary, missing).forEach(function(m) { unsupported.push("tailored_summary claims missing skill: " + m); });
  containsAny(tailored.cover_letter, missing).forEach(function(m) { unsupported.push("cover_letter claims missing skill: " + m); });
  (tailored.tailored_skills_order || []).map(function(s){ return (s||"").toLowerCase(); }).filter(function(s){ return missing.indexOf(s) !== -1; }).forEach(function(m) { unsupported.push("tailored_skills_order claims missing skill: " + m); });
  if ((tailored.cover_letter || "").toLowerCase().indexOf((selectedJob.company || "").toLowerCase()) === -1) { unsupported.push("cover_letter does not mention company name"); }
  if ((tailored.cover_letter || "").toLowerCase().indexOf((selectedJob.job_title || "").toLowerCase()) === -1) { unsupported.push("cover_letter does not mention job title"); }
  const PLACEHOLDER_NAMES = ["john doe", "jane doe"];
  if (PLACEHOLDER_NAMES.some(function(p) { return (tailored.tailored_summary || "").toLowerCase().indexOf(p) !== -1; })) { unsupported.push("tailored_summary contains placeholder name"); }
  const bodyLatex = tailored.tailored_body_latex || "";
  const bodyLower = bodyLatex.toLowerCase();
  const allText = (tailored.tailored_summary || "") + " " + bodyLatex + " " + (tailored.cover_letter || "");
  const allTextLower = allText.toLowerCase();
  PLACEHOLDER_COMPANIES.forEach(function(p) { if (allTextLower.indexOf(p) !== -1) { unsupported.push("placeholder company name detected: " + p); } });
  const yearsInGenerated = (allText.match(/\b(19|20)\d{2}\b/g) || []);
  yearsInGenerated.forEach(function(y) { if (rawLower.indexOf(y) === -1) { unsupported.push("year mentioned in generated content not found in original CV: " + y); } });
  containsAny(bodyLatex, missing).forEach(function(m) { unsupported.push("tailored_body_latex claims missing skill: " + m); });
  if (!bodyLatex.trim()) { unsupported.push("tailored_body_latex is empty"); }
  else if (bodyLower.indexOf("\\section") === -1 && bodyLower.indexOf("\\subsection") === -1) { unsupported.push("tailored_body_latex has no section or subsection commands"); }
  matchedRequired.forEach(function(m) { if (allTextLower.indexOf(m) === -1) { unsupported.push("confirmed matched skill dropped from tailored content: " + m); } });
}
return [{ json: { passed: unsupported.length === 0, unsupported_claims: unsupported, tailored: tailored, candidate_id: candidateId, candidate_email: candidateEmail, original_cv_tex: originalCvTex, selected_job: selectedJob } }];

const input = $input.item.json;
const tailored = input.tailored;
const originalTex = input.original_cv_tex || "";
let preamble = originalTex;
const marker = "\\begin{document}";
const idx = originalTex.indexOf(marker);
if (idx !== -1) { preamble = originalTex.slice(0, idx + marker.length); }
else { preamble = "\\documentclass{article}\n\\begin{document}"; }
const summaryBlock = "\n\\section*{Summary}\n" + (tailored.tailored_summary || "") + "\n";
const body = tailored.tailored_body_latex || "";
const tex = preamble + summaryBlock + body + "\n\\end{document}";
return [{ json: { candidate_id: input.candidate_id, candidate_email: input.candidate_email, selected_job: input.selected_job, tailored: tailored, tailored_tex: tex, fact_check: { unsupported_claims: input.unsupported_claims, passed: input.passed } } }];

