const httpItem = $input.item;
const bin = httpItem.binary && httpItem.binary.data;
const ctx = $("Reassemble Tailored LaTeX").item.json;

let latexCompiled = false;
let cvFile = "PDF compilation failed or the compiler service was unavailable.";
let compileLog = null;

if (bin) {
  try {
    // Read the REAL binary bytes from n8n
    const buf = await this.helpers.getBinaryDataBuffer(0, "data");

    const head = buf.slice(0, 5).toString("utf-8");

    if (head === "%PDF-" && buf.length > 500) {
      latexCompiled = true;

      // Store PDF as base64 data URL
      cvFile =
        "data:application/pdf;base64," +
        buf.toString("base64");
    } else {
      compileLog = buf.toString("utf-8").slice(0, 2000);
    }

  } catch (e) {
    compileLog = "Could not read compiler response body: " + e.message;
  }
}

return [{
  json: {
    candidate_id: ctx.candidate_id,
    candidate_email: ctx.candidate_email,
    selected_job: ctx.selected_job,
    tailored: ctx.tailored,
    tailored_tex: ctx.tailored_tex,
    fact_check: ctx.fact_check,
    latex_compiled: latexCompiled,
    cv_file: cvFile,
    compile_log: compileLog
  }
}];

const item = $input.item;

const dataUrl = item.json.cv_file;

if (!dataUrl || !dataUrl.startsWith("data:application/pdf;base64,")) {
  throw new Error("No valid PDF base64 data found in cv_file");
}

const base64 = dataUrl.split(",")[1];
const buffer = Buffer.from(base64, "base64");

item.binary = item.binary || {};

item.binary.cv_pdf = {
  data: buffer.toString("base64"),
  mimeType: "application/pdf",
  fileName: `${item.json.candidate_id || "candidate"}_${item.json.job_id || "job"}_tailored_cv.pdf`,
  fileExtension: "pdf"
};

return [item];
